LIMIT max OFFSET 2                                         {"columns":["id"],"rows":[[3]]}
LIMIT max（无 OFFSET）                                  {"columns":["id"],"rows":[[1],[2],[3]]}
LIMIT 2 OFFSET max                                         {"columns":["id"],"rows":[]}
距离 + LIMIT max OFFSET 1                                {"columns":["id","d"],"rows":[[2,1.0],[3,2.0]]}
距离 + LIMIT 2 OFFSET 1                                  {"columns":["id","d"],"rows":[[2,1.0],[3,2.0]]}
LIMIT 0 OFFSET max                                         {"columns":["id"],"rows":[]}
OFFSET 超过行数                                        {"columns":["id"],"rows":[]}

