崩溃探针                                               {"columns":["id"],"rows":[[1],[2],[3]]}

varchar_semantics.raw:
###### 1. OFFSET ######
LIMIT 2 OFFSET 1                               {"columns":["id"],"rows":[[2],[3]]}
LIMIT 1,2（MySQL 兼容写法）              {"columns":["id"],"rows":[[2],[3]]}

###### 2. WHERE 字面量超过 VARCHAR 长度 ######
WHERE tag='aaaaaa'（列宽 4）               {"columns":["id"],"rows":[]}
WHERE tag='cc'（正常）                     {"columns":["id"],"rows":[[3]]}

###### 3. SELECT 未知标识符不能当字符串 ######
SELECT foo FROM t                              {"error":"column_not_found"}
SELECT 'foo' FROM t（合法字符串）       {"columns":["foo"],"rows":[["foo"],["foo"],["foo"]]}

###### 4. 畸形数字不能变成 VARCHAR 字面量 ######
SELECT 1abc                                    {"error":"syntax_error"}
WHERE id=1abc                                  {"error":"syntax_error"}

###### 5. 向量列排序必须拒绝 ######
ORDER BY e                                     {"error":"unsupported_sql"}

###### 6. 最大 LIMIT / OFFSET ######
LIMIT 9223372036854775807                      {"columns":["id"],"rows":[[1],[2],[3]]}
LIMIT 0                                        {"columns":["id"],"rows":[]}
OFFSET 超过行数                            {"columns":["id"],"rows":[]}
负 LIMIT                                      {"error":"syntax_error"}

###### 7. 极端距离 ######
极小+极大距离 TopK                       {"columns":["id","d"],"rows":[[3,0.0],[1,9.999999350456404e-39],[2,9.999999680285692e+37]]}
次正规数                                   {"columns":["id"],"rows":[[1]]}

###### 8. 未投影距离的排序（ORDER BY 表达式） ######
ORDER BY L2_DISTANCE(...) 不投影它         {"columns":["id"],"rows":[[1],[2]]}
投影距离但 ORDER BY 主键                {"columns":["id","d"],"rows":[[1,0.0],[2,1.0],[3,2.0]]}

###### 9. 普通别名保留源列名 ######
SELECT id AS x                                 {"columns":["x"],"rows":[[1],[2]]}
SELECT id id2                                  {"error":"syntax_error"}

